@media print {




    table.custom-print-table {

        /*border: 2px solid gold !important;*/



        /*border: 2px solid gold !important;*/
        margin-top: 10px !important;  /* Top margin */
        margin-bottom: 10px !important;  /* Bottom margin */
    }

    table.custom-print-table td{

        font-size:14px !important;

    }
    /*table.custom-print-table td {*/

    /*    font-size:15px !important;*/

    /*}*/


}

/* إخفاء الهيدر والفوتر الافتراضي */
.print-heading,
.letter-head,
.page-footer,
.footer-html {
    display: none !important;
}

/* ضبط المساحات بين الهيدر والفوتر */
@page {
    margin: 100px 20px 80px 20px;   /* زودت المسافة فوق 100px عشان الهيدر */
}

/* صورة الهيدر */
.header-img {
    position: fixed;
    top: -40px;       /* الهيدر ينزل أكثر لو غيرتها لـ -30 أو -20 */
    left: 0;
    width: 100%;
    height: auto;
    z-index: 999;
}

/* صورة الفوتر */
.footer-img {
    position: fixed;
    bottom: -50px;     /* لو الفوتر نازل لتحت زوّد الرقم -40 أو -30 */
    left: 0;
    width: 100%;
    height: auto;
    z-index: 999;
}

/* خط أوضح وأسمك */
body,
.print-format,
table,
td,
th,
div,
span {
    font-family: "Helvetica", Arial, sans-serif !important;
    font-size: 12px !important;    /* أوضح من 11 */
    font-weight: 700 !important;   /* Bold */
    color: #000 !important;
    line-height: 1.35 !important;
}

/* ضبط بداية المحتوى بعد الهيدر */
.print-format {
    margin-top: 25px !important;   /* ينزل الكلام تحت شوية */
}

/* تنسيق الجداول */
table {
    width: 100%;
    border-collapse: collapse !important;
}

table th {
    border: 1px solid #000 !important;
    background: #f3f3f3 !important;
    font-weight: 800 !important;
    text-align: center !important;
    padding: 6px 4px !important;
}

table td {
    border: 1px solid #000 !important;
    padding: 5px !important;
}

/* عنوان الأقسام */
.section-title {
    font-size: 13px !important;
    font-weight: 800 !important;
    text-decoration: underline;
    margin-top: 15px !important;
}

/* صندوق الـ Subject */
.q-box {
    border: 1px solid #000 !important;
    padding: 7px !important;
    margin-bottom: 10px !important;
}

/* توقيع */
.signature-block {
    margin-top: 25px !important;
    font-size: 12px !important;
    font-weight: 700 !important;
}

/* ============================= */
/*      AUTO SERIAL NUMBERS      */
/* ============================= */

.q-table {
    counter-reset: rowNumber;
}

.q-table tbody tr {
    counter-increment: rowNumber;
}

.q-table tbody tr td:first-child::before {
    content: counter(rowNumber);
}
.q-sub-header {
    text-align: center;
    font-size: 10px;
    margin-bottom: 10px;
}
.q-header {
    text-align: center;
    margin-bottom: 6px;
}

.q-header h2 {
    margin: 0;
    font-size: 16px;
    font-weight: 800;
    text-transform: uppercase;
}

html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set customer = frappe.get_doc("Customer", doc.party_name) if doc.quotation_to == "Customer" else None %}
{% set item_region = frappe.get_doc("Item Region", doc.custom_item_region) if doc.custom_item_region else None %}
{% set print_data = frappe.call("swift_arrow.swift_arrow.doctype.item_region.item_region.get_print_format_data", docname=doc.custom_item_region) if doc.custom_item_region else None %}
{# ================= COMPANY ADDRESS VIA DYNAMIC LINK ================= #}

{% set company_address_name = frappe.db.sql("""
    SELECT addr.name
    FROM `tabAddress` addr
    INNER JOIN `tabDynamic Link` dl
        ON dl.parent = addr.name
    WHERE dl.link_doctype = 'Company'
        AND dl.link_name = %s
        AND addr.is_your_company_address = 1
    LIMIT 1
""", company.name, as_dict=1) %}
{% set company_address = frappe.get_doc("Address", company_address_name[0].name) if company_address_name else None %}
{# ================= COMPANY CONTACT LINKED TO ADDRESS ================= #}

{% set company_contact_name = frappe.db.sql("""
    SELECT name
    FROM `tabContact`
    WHERE address = %s
    LIMIT 1
""", company_address.name if company_address else "", as_dict=1) %}

{% set company_contact = frappe.get_doc("Contact", company_contact_name[0].name) if company_contact_name else None %}

{% set company_full_address = company_address.get_display() if company_address else "" %}
{% set company_phone = (company.phone_no) if company_contact else "" %}
{% set company_email = company.email if company_contact else "" %}
{% set custom_represented_by = company.custom_represented_by if company.custom_represented_by else "" %}

<style>
    @page {
        size: A4;
        margin: 5mm;
    }
    
    body {
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        font-size: 6pt;
        direction: rtl;
        text-align: right;
    }
    
    .print-format {
        padding: 10px;
    }
    
    .header-table {
        width: 100%;
        border-bottom: 3px solid #fbd4b4;
        padding-bottom: 10px;
        margin-bottom: 15px;
    }
    
    .header-table td {
        vertical-align: middle;
    }
    
    .company-info-left {
        text-align: left;
        font-size: 9pt;
    }
    
    .company-info-right {
        text-align: right;
        font-size: 9pt;
    }
    
    .logo-center {
        text-align: center;
    }
    
    .logo-center img {
        max-height: 70px;
    }
    
    .title-section {
        text-align: center;
        margin: 15px 0;
    }
    
    .title-section h2 {
        color: #333;
        margin: 3px 0;
        font-size: 14pt;
    }
    
    .intro-text {
        font-weight: bold;
        padding: 6px;
        border-radius: 5px;
        margin-bottom: 10px;
        line-height: 1.6;
        text-align: right;
        font-size: 9pt;
    }
    
    .party-section {
        margin-bottom: 15px;
        
    }
    .party-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background-color: #fbd4b4;
    padding: 6px 12px;
    font-weight: bold;
    font-size: 10pt;
}

.party-header-left {
    text-align: left;
}

.party-header-right {
    text-align: right;
}

    .party-header {
        background-color: #fbd4b4;
        color: black;
        padding: 6px 12px;
        font-weight: bold;
        text-align: right;
        font-size: 10pt;
    }
        .party-header-right {
        background-color: #fbd4b4;
        color: black;
        padding: 6px 12px;
        font-weight: bold;
        text-align: left;
        font-size: 10pt;
    }
    
    .party-table {
        width: 100%;
        border-collapse: collapse;
    }
    
    .party-table td {
        padding: 5px 8px;
        border: 1px solid #ddd;
        font-size: 9pt;
    }
    
    .party-table .label {
        background-color: #f5f5f5;
        font-weight: bold;
        width: 15%;
    }
    
    .party-table .value {
        width: 35%;
    }
    
    .intro-section {
        margin: 15px 0;
    }
    
    .intro-header {
        background-color: #fbd4b4;
        color: black;
        padding: 6px 12px;
        font-weight: bold;
        font-size: 10pt;
    }
    
    .intro-content-table {
        width: 100%;
        border: 1px solid #ddd;
        border-collapse: collapse;
    }
    
    .intro-content-table td {
        padding: 10px;
        line-height: 1.6;
        font-size: 9pt;
        vertical-align: top;
        width: 50%;
    }
    
    .intro-content-table .col-left {
        text-align: left;
        border-right: 1px solid #ddd;
    }
    
    .intro-content-table .col-right {
        text-align: right;
    }
    
    .proposal-section {
        margin: 20px 0;
    }
    
    .proposal-header {
        color: #2980b9;
        font-size: 12pt;
        font-weight: bold;
        margin-bottom: 10px;
    }
    
    .service-title {
        color: black;
        padding: 6px 12px;
        text-align: right;
        font-weight: bold;
        margin: 10px 0 8px 0;
        font-size: 10pt;
    }
    
    .data-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 15px;
    }
    
    .data-table th {
        background-color: #ecf0f1;
        padding: 6px;
        border: 1px solid #bdc3c7;
        text-align: center;
        font-size: 9pt;
    }
    
    .data-table td {
        padding: 5px;
        border: 1px solid #bdc3c7;
        text-align: center;
        font-size: 9pt;
    }
    
    .region-table {
        width: 100%;
        border-collapse: collapse;
        margin: 15px 0;
    }
    
    .region-table th {
        color: black;
        padding: 6px;
        border: 1px solid #2980b9;
        text-align: center;
        font-size: 9pt;
    }
    
    .region-table td {
        padding: 4px;
        border: 1px solid #bdc3c7;
        text-align: center;
        font-size: 9pt;
    }
    
    .region-table tr:nth-child(even) {
        background-color: #f9f9f9;
    }
    
    .zone-cell {
        background-color: #e8f4fc;
        font-weight: bold;
        width: 30px;
    }
    
    .notes-section {
        margin: 20px 0;
    }
    
    .notes-header {
        color: black;
        padding: 6px 12px;
        text-align: right;
        font-weight: bold;
        font-size: 10pt;
    }
    
    .notes-content {
        border: 1px solid #ddd;
        padding: 10px;
        line-height: 1.8;
        font-size: 9pt;
    }
    
    .notes-content ol {
        margin: 0;
        padding-right: 20px;
    }
    
    .closing-section {
        text-align: center;
        margin: 20px 0;
        padding: 15px;
        background-color: #fff8e1;
        border-radius: 5px;
    }
    
    .closing-section p {
        font-size: 11pt;
        color: #fbd4b4
        font-weight: bold;
        margin: 3px 0;
    }
    
    .page-footer {
        text-align: center;
        margin-top: 20px;
        padding-top: 8px;
        border-top: 1px solid #ddd;
        font-size: 9pt;
        color: #666;
    }
    
    .custom-table-section table {
        width: 100%;
        border-collapse: collapse;
        margin: 10px 0;
    }
    
    .custom-table-section th {
        background-color: #ecf0f1;
        padding: 6px;
        border: 1px solid #bdc3c7;
        text-align: center;
        font-size: 9pt;
    }
    
    .custom-table-section td {
        padding: 5px;
        border: 1px solid #bdc3c7;
        text-align: center;
        font-size: 9pt;
    }
</style>

<div class="print-format">
    <!-- Header Section -->
    <table class="header-table">
        <tr>
            <td class="company-info-left" style="width: 30%;">
                <strong>SWIFT ARROW</strong><br>
                C.R. {{ company.tax_id or "7051005440" }}
            </td>
            <td class="logo-center" style="width: 40%;">
                {% if company.company_logo %}
                <img src="{{ company.company_logo }}" alt="Company Logo">
                {% else %}
                <img src="/assets/swift_arrow/images/swift arrow N2_page-0001.jpg" alt="Swift Arrow Logo" style="max-height: 70px;margin-top:-20px;">
                {% endif %}
            </td>
            <td class="company-info-right" style="width: 30%;">
                <strong>شركة سويفت أرو</strong><br>
                سجل تجاري رقم: {{ company.tax_id or "7051005440" }}
            </td>
        </tr>
    </table>

    <!-- Title Section -->
    <div class="title-section">
        <h2>عرض سعر نقليات</h2>
        <h2>Transportation offer price</h2>
    </div>

<div class="intro-text">
    <span class="no-wrap">
        نشكركم على إتاحة الفرصة لنا لتقديم هذا العرض والمختص بالخدمات اللوجستية
    </span>
    ولتميزنا في مجال الخدمات اللوجستية فقد سعت إدارة الشركة إلى تطوير هذه الخدمة بما يتماشى مع متطلبات عملائنا الكرام، وأذ نأمل تقديم
    خدماتنا إلى عملائنا بما يتماشى مع متطلبات إعمالهم واحتياجاتهم. فنحن نعمل على نقل المهام والعمليات الخاصة بأعمالكم ونقل وتوزيع الشحنات
    بأنواعها وتنظيم وإدارة عمليات الشحن على مستوى المملكة بلا استثناء.
</div>

    <!-- First Party Section -->
    <div class="party-section">
        <div class="party-header-row">
            <div class="party-header-right">(الطرف الأول)</div>
            <div class="party-header">(FIRST PARTY)</div>
        </div>
        <table class="party-table">
            <tr>
                <td >اسم الشركة:</td>
                <td class="value">{{ company.company_name_in_arabic or "سويفت أرو" }}</td>
                <td >Company name:</td>
                <td class="value">{{ company.company_name or "SWIFT ARROW" }}</td>
            </tr>
            <tr>
                <td >العنوان:</td>
                <td class="value">{{ company_full_address }}</td>
                <td >Address:</td>
                <td class="value">{{ company_full_address }}</td>
            </tr>
            <tr>
                <td >رقم الهاتف:</td>
                <td class="value">{{ company_phone }}</td>
                <td >Telephone number:</td>
                <td class="value">{{ company_phone }}</td>
            </tr>
            <tr>
                <td >البريد الالكتروني:</td>
                <td class="value">{{ company_email }}</td>
                <td >Email:</td>
                <td class="value">{{ company_email }}</td>
            </tr>
            <tr>
                <td>الرقم الضريبي:</td>
                <td class="value">{{ company.custom_tax_registration or company.tax_id or "" }}</td>
                <td>Tax ID:</td>
                <td class="value">{{ company.custom_tax_registration or company.tax_id or "" }}</td>
            </tr>
            <tr>
                <td >ويمثلها:</td>
                <td class="value">{{ custom_represented_by or "" }}</td>
                <td >Represented by:</td>
                <td class="value">{{ custom_represented_by or "" }}</td>
            </tr>
        </table>
    </div>

    <!-- Second Party Section -->
    <div class="party-section">
        <div class="party-header-row">
            <div class="party-header-right">(الطرف الثاني)</div>
            <div class="party-header">(SECOND PARTY)</div>
        </div>
        <table class="party-table">
            <tr>
                <td >اسم الشركة:</td>
                <td class="value">{{ customer.customer_name if customer else doc.customer_name or "" }}</td>
                <td >Company Name:</td>
                <td class="value">{{customer.customer_name if customer else doc.customer_name or ""  }}</td>
            </tr>
            <tr>
                <td >العنوان:</td>
                <td class="value">{{ doc.custom_address or "" }}</td>
                <td >Address:</td>
                <td class="value">{{ doc.custom_address or "" }}</td>
            </tr>
            <tr>
                <td >رقم الهاتف:</td>
                <td class="value">{{ doc.custom_telephone_number or "" }}</td>
                <td >Telephone Number</td>
                <td class="value">{{ doc.custom_telephone_number or "" }}</td>
            </tr>
            <tr>
                <td >البريد الالكتروني:</td>
                <td class="value">{{ doc.custom_email or "" }}</td>
                <td >Email:</td>
                <td class="value">{{ doc.custom_email or "" }}</td>
            </tr>
            <tr>
            <td>الرقم الضريبي:</td>
                <td class="value">
                    {{ customer.tax_id if customer and customer.tax_id else doc.tax_id or "" }}
                </td>
                <td>Tax ID:</td>
                <td class="value">
                    {{ customer.tax_id if customer and customer.tax_id else doc.tax_id or "" }}
                </td>
            </tr>
            <tr>
                <td >ويمثلها:</td>
                <td class="value">{{ doc.custom_represented_by or "" }}</td>
                <td >Represented by:</td>
                <td class="value">{{ doc.custom_represented_by or "" }}</td>
            </tr>
        </table>

    </div>

    <!-- Introduction Section -->
    <div class="intro-section">
        <div style="display: flex; justify-content: space-between;background-color: #fbd4b4;">
            <div class="intro-header"> | مقدمة</div>
            <div class="intro-header">INTRODUCTION</div>
        </div>
        <table class="intro-content-table">
            <tr>

                <td class="col-right">
                    حيث أن الطرف الأول مؤسسة متخصصة بتقديم خدمة نقل البضائع على
                    الطرق البرية، بموجب
                    السجل التجاري رقم ( {{ company.tax_id or "7051005440" }})
                    الرقم الضريبي : ({{ company.custom_tax_registration or "314084600400003" }})
                    وتاريخ {{ frappe.format_date(doc.transaction_date) }}، وقد قدم عرضه بتزويد الطرف الثاني
                    بمركبات بسائق ذات أحجام مختلفة وذات مواصفات محددة ليتم استخدامها
                    في نقل المنتجات على الطرق البرية، سواء كانت المركبات مملوكة
                    للطرف الأول أو مستأجرة من الغير عن طريق تعاقد الطرف الأول مع
                    أطراف أخرى.
                </td>
                <td class="col-left">
                    The first party, an establishment specializing in
                    providing road freight transport services, under
                    Commercial Registration No. ({{ company.tax_id or "7051005440" }}) and
                    Tax Registration No. ({{ company.custom_tax_registration or "314084600400003" }}), dated
                    {{ frappe.format_date(doc.transaction_date) }}, has offered to supply the
                    second party with vehicles of varying sizes and
                    specifications, with drivers, for use in transporting
                    products by road. These vehicles may be owned
                    by the first party or leased from third parties
                    through contracts between the first party and other
                    parties.
                </td>
            </tr>
        </table>
    </div>

    <!-- Page Break for Proposal -->
    <div style="page-break-before: always;"></div>
    
    <!-- Header on new page -->
    <table class="header-table">
        <tr>
            <td class="company-info-left" style="width: 30%;">
                <strong>SWIFT ARROW</strong><br>
                C.R. {{ company.tax_id or "7051005440" }}
            </td>
            <td class="logo-center" style="width: 40%;">
                {% if company.company_logo %}
                <img src="{{ company.company_logo }}" alt="Company Logo">
                {% else %}
                <img src="/assets/swift_arrow/images/swift arrow N2_page-0001.jpg" alt="Swift Arrow Logo" style="max-height: 70px;margin-top:-20px;">
                {% endif %}
            </td>
            <td class="company-info-right" style="width: 30%;">
                <strong>شركة سويفت أرو</strong><br>
                سجل تجاري رقم: {{ company.tax_id or "7051005440" }}
            </td>
        </tr>
    </table>

    <!-- Proposal Section -->
    <div class="proposal-section">
        <div class="proposal-header">PROPOSAL.</div>

<table class="data-table">
    <thead>
        <tr>
            <th>الصنف</th>
            <th>من</th>
            <th>إلي</th>
            <th>السعر</th>
        </tr>
    </thead>
    <tbody>
        {% for item in doc.items %}
        <tr>
            <td>{{ item.item_name or "" }}</td>
            <td>{{ item.custom_origin_city or "" }}</td>
            <td>{{ item.custom_destination_city or "" }}</td>
            <td>{{ item.amount or "" }}</td>
        </tr>
        {% endfor %}
    </tbody>
</table>
        {% if item_region %}
            <div class="service-title">{{ item_region.type or "خدمات النقل المحلي الجاف اكسبريس" }}</div>
            
            <!-- Custom Type1 Table (المستندات) -->
            {% if doc.custom_type1 %}
            <div class="service-title" style="background-color: #95a5a6;">المستندات</div>
            <div class="custom-table-section">
                {{ doc.custom_type1 | safe }}
            </div>
            {% endif %}
            
            <!-- Custom Type2 Table (الطرود) -->
            {% if doc.custom_type2 %}
            <div class="service-title" style="background-color: #95a5a6;">الطرود</div>
            <div class="custom-table-section">
                {{ doc.custom_type2 | safe }}
            </div>
            {% endif %}
            
            <!-- International Transport Services Table -->
            {% if print_data and print_data.types %}
            {% for type_data in print_data.types %}
            <div class="service-title">{{ type_data.type }}</div>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>الوزن (كجم)</th>
                        {% for region in type_data.regions %}
                        <th>{{ region }}</th>
                        {% endfor %}
                    </tr>
                </thead>
                <tbody>
                    {% for row in type_data.data %}
                    <tr>
                        <td><strong>{{ row.quantity }} كجم</strong></td>
                        {% for region in type_data.regions %}
                        <td>{{ row.rates.get(region, '') }}</td>
                        {% endfor %}
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
            {% endfor %}
            {% endif %}
        {% endif %}
    </div>


    <!-- Notes Section -->
    <div class="notes-section">
        <div class="notes-header">ملاحظات على الأسعار</div>
        <div class="notes-content">
            <ol>
                <li>بخصوص الأوزان يتم احتسابها بناء على الوزن الفعلي أو الوزن الحجمي أيهما أكبر.</li>
                <li>يتم احتساب الوزن الحجمي = (الطول بالسم × العرض بالسم × الارتفاع بالسم) ÷ 5000</li>
                <li>بخصوص أسعار الطبليات أو البالت سعر لكل منصة نقلة (بشرط ألا يتجاوز الحجم 1.5 متر مكعب لكل منصة وألا يزيد الوزن عن 500 كجم). وإذا زادت حجم الطبلية أو البالت عن الحجم المعتاد يتم احتساب طبالي إو بالت إضافي.</li>
                <li>بخصوص الشحنات يتم احتسابها بيوم إضافة عند التحميل من أكثر من موقع والتنزيل في أكثر من موقع.</li>
