html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set customer = frappe.get_doc("Customer", doc.party_name) if doc.quotation_to == "Customer" else None %}
{% set item_region = frappe.get_doc("Item Region", doc.custom_item_region) if doc.custom_item_region else None %}
{% set print_data = frappe.call("swift_arrow.swift_arrow.doctype.item_region.item_region.get_print_format_data", docname=doc.custom_item_region) if doc.custom_item_region else None %}

{% set company_address_name = frappe.db.sql("""
    SELECT addr.name FROM `tabAddress` addr
    INNER JOIN `tabDynamic Link` dl ON dl.parent = addr.name
    WHERE dl.link_doctype = 'Company' AND dl.link_name = %s AND addr.is_your_company_address = 1
    LIMIT 1
""", company.name, as_dict=1) %}
{% set company_address = frappe.get_doc("Address", company_address_name[0].name) if company_address_name else None %}
{% set company_full_address = company_address.get_display() if company_address else "" %}
{% set company_phone = company.phone_no if company.phone_no else "" %}
{% set company_email = company.email if company.email else "" %}
{% set custom_represented_by = company.custom_represented_by if company.custom_represented_by else "" %}

<style>
    @page { size: A4; margin: 10mm 8mm; }
    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
        font-family: 'Segoe UI', Tahoma, Arial, sans-serif;
        font-size: 11pt;
        direction: ltr;
        text-align: left;
        color: #1a1a1a;
        background: white;
    }

    .page-wrap { padding: 4px 6px; }

    /* HEADER */
    .header-tbl { width: 100%; border-collapse: collapse; border-bottom: 3px solid #f5a623; margin-bottom: 12px; }
    .header-tbl td { vertical-align: middle; padding: 4px 6px 10px 6px; }
    .h-en  { text-align: left;   font-size: 10pt; line-height: 1.6; width: 33%; }
    .h-ctr { text-align: center; width: 34%; }
    .h-ar  { text-align: right;  font-size: 10pt; line-height: 1.6; width: 33%; direction: rtl; }
    .h-en strong, .h-ar strong { font-size: 12pt; display: block; }
    .h-ctr img { max-height: 65px; }

    /* TITLE */
    .doc-title { text-align: center; margin: 10px 0 12px; font-size: 16pt; font-weight: bold; color: #222; }

    /* INTRO TEXT */
    .intro-text { font-size: 10.5pt; line-height: 1.8; padding: 8px 12px; border-left: 4px solid #f5a623; background: #fffaf5; margin-bottom: 12px; }

    /* SECTION HEADER */
    .sec-hdr { background: #fbd4b4; font-weight: bold; font-size: 11pt; padding: 6px 12px; }

    /* ══ SIDE-BY-SIDE PARTIES ══ */
    .parties-wrap {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 12px;
    }
    .parties-wrap > tbody > tr > td {
        vertical-align: top;
        width: 50%;
        padding: 0;
    }
    .parties-wrap > tbody > tr > td:first-child {
        padding-right: 5px;
    }
    .parties-wrap > tbody > tr > td:last-child {
        padding-left: 5px;
    }

    /* PARTY TABLE */
    .party-block { width: 100%; }
    .party-block .sec-hdr { margin-bottom: 0; }

    .party-tbl { width: 100%; border-collapse: collapse; }
    .party-tbl td { padding: 5px 8px; border: 1px solid #ddd; font-size: 9.5pt; line-height: 1.4; }
    .party-tbl .lbl { background: #f5f5f5; font-weight: bold; width: 38%; white-space: nowrap; }

    /* INTRO BOX */
    .intro-box { border: 1px solid #ddd; font-size: 10.5pt; line-height: 1.8; padding: 10px 14px; margin-bottom: 0; }

    /* PROPOSAL LABEL */
    .proposal-lbl { font-size: 13pt; font-weight: bold; color: #c0620a; padding: 4px 0; border-bottom: 2px solid #f5a623; margin: 10px 0 8px; }

    /* DATA TABLE */
    .data-tbl { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
    .data-tbl th { background: #ecf0f1; border: 1px solid #bdc3c7; padding: 7px 6px; text-align: center; font-size: 10.5pt; }
    .data-tbl td { border: 1px solid #bdc3c7; padding: 6px; text-align: center; font-size: 10.5pt; }
    .data-tbl tr:nth-child(even) td { background: #fafafa; }

    /* SERVICE TITLE */
    .svc-title { font-weight: bold; font-size: 10.5pt; padding: 5px 10px; margin: 10px 0 4px; border-left: 4px solid #f5a623; background: #fffaf5; }

    /* CUSTOM TABLE */
    .custom-tbl table { width: 100%; border-collapse: collapse; margin: 6px 0; }
    .custom-tbl th { background: #ecf0f1; border: 1px solid #bdc3c7; padding: 6px; text-align: center; font-size: 10pt; }
    .custom-tbl td { border: 1px solid #bdc3c7; padding: 5px; text-align: center; font-size: 10pt; }

    /* ══ NOTES — fixed alignment ══ */
    .notes-wrap {
        border: 1px solid #ddd;
        padding: 10px 14px;
        font-size: 10.5pt;
        line-height: 1.9;
        margin-bottom: 12px;
        text-align: left;
    }
    /* Reset any RTL or center alignment that ERPNext terms may inject */
    .notes-wrap * {
        text-align: left !important;
        direction: ltr !important;
    }
    /* Style ordered lists nicely */
    .notes-wrap ol,
    .notes-wrap ul {
        padding-left: 20px;
        margin: 4px 0;
    }
    .notes-wrap li {
        margin-bottom: 5px;
    }
    /* Plain paragraph terms (no list tags) */
    .notes-wrap p {
        margin-bottom: 6px;
    }

    /* CLOSING */
    .closing { text-align: center; padding: 12px; background: #fff8f0; border: 1px solid #fbd4b4; font-size: 11pt; line-height: 2; margin-bottom: 12px; color: #c0620a; font-weight: bold; }

    /* FOOTER */
    .pg-footer { text-align: center; border-top: 1px solid #ddd; padding-top: 6px; font-size: 9.5pt; color: #888; margin-top: 10px; }
</style>

<div class="page-wrap">

    <!-- ══ HEADER ══ -->
    <table class="header-tbl">
        <tr>
            <td class="h-en"><strong>SWIFT ARROW</strong>C.R. {{ company.tax_id or "7051005440" }}</td>
            <td class="h-ctr">
                {% if company.company_logo %}<img src="{{ company.company_logo }}" alt="Logo">
                {% else %}<img src="/assets/swift_arrow/images/swift arrow N2_page-0001.jpg" alt="Swift Arrow Logo">{% endif %}
            </td>
            <td class="h-ar"><strong>شركة سويفت أرو</strong>سجل تجاري رقم: {{ company.tax_id or "7051005440" }}</td>
        </tr>
    </table>

    <div class="doc-title">Transportation Price Offer</div>

    <div class="intro-text">
        We thank you for the opportunity to present this offer, which specializes in logistics services.
        Leveraging our excellence in the field of logistics, the company's management has sought to develop
        this service in line with the requirements of our valued clients. We aspire to provide our services
        in a manner that aligns with the needs of your business. We handle the transfer of tasks and operations
        specific to your work, as well as the transportation and distribution of shipments of all kinds,
        and the organization and management of shipping operations across the Kingdom without exception.
    </div>

    <!-- ══ FIRST & SECOND PARTY — SIDE BY SIDE ══ -->
    <table class="parties-wrap">
        <tbody>
            <tr>
                <!-- FIRST PARTY -->
                <td>
                    <div class="party-block">
                        <div class="sec-hdr">FIRST PARTY</div>
                        <table class="party-tbl">
                            <tr><td class="lbl">Company Name</td><td>{{ company.company_name or "SWIFT ARROW" }}</td></tr>
                            <tr><td class="lbl">Address</td><td>{{ company_full_address }}</td></tr>
                            <tr><td class="lbl">Telephone</td><td>{{ company_phone }}</td></tr>
                            <tr><td class="lbl">Email</td><td>{{ company_email }}</td></tr>
                            <tr><td class="lbl">Tax ID</td><td>{{ company.custom_tax_registration or company.tax_id or "" }}</td></tr>
                            <tr><td class="lbl">Represented by</td><td>{{ doc.custom_sales_person or "" }}</td></tr>
                        </table>
                    </div>
                </td>

                <!-- SECOND PARTY -->
                <td>
                    <div class="party-block">
                        <div class="sec-hdr">SECOND PARTY</div>
                        <table class="party-tbl">
                            <tr><td class="lbl">Company Name</td><td>{{ customer.customer_name if customer else doc.customer_name or "" }}</td></tr>
                            <tr><td class="lbl">Address</td><td>{{ doc.custom_address or "" }}</td></tr>
                            <tr><td class="lbl">Telephone</td><td>{{ doc.custom_telephone_number or "" }}</td></tr>
                            <tr><td class="lbl">Email</td><td>{{ doc.custom_email or "" }}</td></tr>
                            <tr><td class="lbl">Tax ID</td><td>{{ customer.tax_id if customer and customer.tax_id else doc.tax_id or "" }}</td></tr>
                            <tr><td class="lbl">Represented by</td><td>{{ doc.custom_represented_by or "" }}</td></tr>
                        </table>
                    </div>
                </td>
            </tr>
        </tbody>
    </table>

    <!-- ══ INTRODUCTION ══ -->
    <div class="sec-hdr">INTRODUCTION</div>
    <div class="intro-box">
        The first party, an establishment specializing in providing road freight transport services,
        under Commercial Registration No. ({{ "7051005440" }}) and
        Tax Registration No. ({{ company.custom_tax_registration or "314084600400003" }}),
        Dated {{ doc.transaction_date }},
        has offered to supply the second party with vehicles of varying sizes and specifications, with drivers,
        for use in transporting products by road. These vehicles may be owned by the first party or leased
        from third parties through contracts between the first party and other parties.
    </div>

    <div class="proposal-lbl">PROPOSAL</div>

    <table class="data-tbl">
        <thead>
            <tr><th>Item</th><th>From</th><th>To</th><th>Price</th></tr>
        </thead>
        <tbody>
            {% for item in doc.items %}
            <tr>
                <td>{{ item.item_name or "" }}</td>
                <td>{{ item.custom_origin_city or "" }}</td>
                <td>{{ item.custom_destination_city or "" }}</td>
                <td>{{ item.amount or "" }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {% if item_region %}
    <div class="svc-title">{{ item_region.type or "Local Dry Express Transport Services" }}</div>
    {% if doc.custom_type1 %}
    <div class="svc-title" style="background:#f0f0f0;border-left-color:#aaa;">Documents</div>
    <div class="custom-tbl">{{ doc.custom_type1 | safe }}</div>
    {% endif %}
    {% if doc.custom_type2 %}
    <div class="svc-title" style="background:#f0f0f0;border-left-color:#aaa;">Parcels</div>
    <div class="custom-tbl">{{ doc.custom_type2 | safe }}</div>
    {% endif %}
    {% if print_data and print_data.types %}
    {% for type_data in print_data.types %}
    <div class="svc-title">{{ type_data.type }}</div>
    <table class="data-tbl">
        <thead><tr><th>Weight (kg)</th>{% for region in type_data.regions %}<th>{{ region }}</th>{% endfor %}</tr></thead>
        <tbody>
            {% for row in type_data.data %}
            <tr>
                <td><strong>{{ row.quantity }} kg</strong></td>
                {% for region in type_data.regions %}<td>{{ row.rates.get(region, '') }}</td>{% endfor %}
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endfor %}
    {% endif %}
    {% endif %}

    <!-- ══ NOTES — properly aligned ══ -->
    <div class="sec-hdr">Notes</div>
    <div class="notes-wrap">
        {{ doc.terms }}
    </div>

    <div class="closing">
        We hope our offer meets your approval and satisfaction,<br>
        Please accept our sincere regards and respect!!
    </div>

    <div class="pg-footer">Page</div>
</div>

{% set company = frappe.get_doc("Company", doc.company) %}
{% set lh_name =
    doc.letter_head
    or company.default_letter_head
    or frappe.db.get_value("Letter Head", {"is_default": 1, "disabled": 0}, "name")
%}
{% set header_text = lh_name and frappe.db.get_value("Letter Head", lh_name, "content") or "" %}
{% set footer_text = lh_name and frappe.db.get_value("Letter Head", lh_name, "footer") or "" %}

<!-- Header Section -->
{% if header_text %}
<div class="header-section">
  {{ header_text }}
</div>
{% endif %}

<!-- Document Name -->
<div style="text-align:center; font-size:20px; font-weight:bold; margin:15px 0;">
  عرض سعر
</div>

<style>
  .header-table {
    width: 100%;
    margin-bottom: 20px;
    border-collapse: collapse;
    direction: rtl;
  }
  .header-table td {
    padding: 6px;
    font-size: 14px;
    text-align: right;
  }
  
  .boq-container {
    direction: rtl;
  }
  
  table.boq-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 30px;
    page-break-inside: auto;
    margin-right: 15px;
    direction: rtl;
  }
  
  table.boq-table th,
  table.boq-table td {
    border: 0.5px solid #666;
    padding: 8px;
    text-align: right;
    word-wrap: break-word;
    box-sizing: border-box;
    font-size: 13px;
  }
  
  table.boq-table th {
    background-color: #f2f2f2;
    font-weight: bold;
    text-align: center;
  }
  
  .num-col {
    text-align: center !important;
  }
  
  .item-no {
    font-weight: bold;
  }
  
  .section-title {
    font-size: 16px;
    font-weight: bold;
    margin-top: 20px;
    margin-bottom: 8px;
    text-align: right;
    direction: rtl;
  }
  
  .total-container {
    direction: rtl;
  }
  
  table.total_table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
    font-size: 14px;
    direction: rtl;
  }
  
  table.total_table td {
    border: 0.5px solid #666;
    padding: 6px;
    font-weight: 900;
    text-align: right;
  }
  
  table.total_table td:last-child {
    text-align: center;
  }
  
  .signature {
    margin-top: 50px;
    text-align: right;
    font-size: 16px;
    direction: rtl;
  }
  .signature-line {
    margin-top: 40px;
    border-top: 0.5px solid #666;
    width: 250px;
    margin-right: 0;
  }
  
  .footer-section {
    margin-top: 40px;
    text-align: center;
    font-size: 12px;
  }
</style>

<!-- Document Fields -->
<table class="header-table">
  <tr>
    <td><strong>العميل:</strong> {{ doc.party_name or "" }}</td>
    <td><strong>التاريخ:</strong> {{ frappe.utils.formatdate(doc.transaction_date) if doc.transaction_date else "" }}</td>
  </tr>
  <tr>
    <td><strong>رقم العرض:</strong> {{ doc.name or "" }}</td>
    <td><strong>العملة:</strong> {{ doc.currency or "SAR" }}</td>
  </tr>
</table>

<!-- Items Table -->
<div class="boq-container">
  <table class="boq-table">
    <thead>
      <tr>
        <th>Sr</th>
        <th>البند</th>
        <th>الوصف</th>
        <th>الوحدة</th>
        <th>الكمية</th>
        <th>السعر</th>
        <th>المبلغ ({{ doc.currency or "SAR" }})</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
        <tr>
          <td class="num-col">{{ loop.index }}</td>
          <td class="item-no">{{ row.item_code or "" }}</td>
          <td>{{ row.description or "" }}</td>
          <td class="num-col">{{ row.uom or "" }}</td>
          <td class="num-col">{{ row.qty or "" }}</td>
          <td class="num-col">{{ row.rate or "" }}</td>
          <td class="num-col">{{ row.amount or "" }}</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>
</div>
<!-- Totals Section -->
<div class="total-container">
  <div class="section-title">الإجماليات</div>
  <table class="total_table">
    <tr>
      <td>الاجمالي بدون ضريبه ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("total") }}</td>
    </tr>
    <tr>
      <td>اجمالي الضريبة  ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("total_taxes_and_charges") }}</td>
    </tr>
    <tr>
      <td>الاجمالي مع الضريبة  ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("grand_total") }}</td>
    </tr>
  </table>
</div>
<!-- Payment Terms Table -->
{% if doc.payment_schedule %}
<div class="total-container">
  <div class="section-title">شروط الدفع / Payment Terms</div>
  <table class="total_table">
    <thead>
      <tr>
         <td><strong>البند / Payment Term</strong></td>
        <td><strong>نسبة الدفع / Invoice Portion%</strong></td>
        <td><strong>التاريخ / Date</strong></td>
        <td><strong>المبلغ / Amount</strong></td>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.payment_schedule %}
      <tr>
         <td>{{ row.payment_term or "" }}</td>
        <td>{{ row.invoice_portion or "" }}</td>
        <td>{{ frappe.utils.formatdate(row.due_date) if row.due_date else "" }}</td>
        <td>{{ row.payment_amount or "" }}</td>


      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>
{% endif %}
