{% set company = frappe.get_doc("Company", doc.company) %}
{% set lh_name =
    doc.letter_head
    or company.default_letter_head
    or frappe.db.get_value("Letter Head", {"is_default": 1, "disabled": 0}, "name")
%}
{% set header_text = lh_name and frappe.db.get_value("Letter Head", lh_name, "content") or "" %}
{% set footer_text = lh_name and frappe.db.get_value("Letter Head", lh_name, "footer") or "" %}

<!-- Header Section -->
{% if header_text %}
<div class="header-section">
  {{ header_text }}
</div>
{% endif %}

<!-- Document Name -->
<div style="text-align:center; font-size:20px; font-weight:bold; margin:15px 0;">
  عرض سعر
</div>

<style>
  .header-table {
    width: 100%;
    margin-bottom: 20px;
    border-collapse: collapse;
    direction: rtl;
  }
  .header-table td {
    padding: 6px;
    font-size: 14px;
    text-align: right;
  }
  
  .boq-container {
    direction: rtl;
  }
  
  table.boq-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 30px;
    page-break-inside: auto;
    margin-right: 15px;
    direction: rtl;
  }
  
  table.boq-table th,
  table.boq-table td {
    border: 0.5px solid #666;
    padding: 8px;
    text-align: right;
    word-wrap: break-word;
    box-sizing: border-box;
    font-size: 13px;
  }
  
  table.boq-table th {
    background-color: #f2f2f2;
    font-weight: bold;
    text-align: center;
  }
  
  .num-col {
    text-align: center !important;
  }
  
  .item-no {
    font-weight: bold;
  }
  
  .group-row td {
    background-color: #e8e8e8;
    font-weight: bold;
    font-size: 15px;
    border: 0.5px solid #666;
    text-align: center;
    vertical-align: middle;
    padding: 10px 8px;
  }
  
  .section-title {
    font-size: 16px;
    font-weight: bold;
    margin-top: 20px;
    margin-bottom: 8px;
    text-align: right;
    direction: rtl;
  }
  
  .total-container {
    direction: rtl;
  }
  
  table.total_table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
    font-size: 14px;
    direction: rtl;
  }
  
  table.total_table td {
    border: 0.5px solid #666;
    padding: 6px;
    font-weight: 900;
    text-align: right;
  }
  
  table.total_table td:last-child {
    text-align: center;
  }
  
  .signature {
    margin-top: 50px;
    text-align: right;
    font-size: 16px;
    direction: rtl;
  }
  .signature-line {
    margin-top: 40px;
    border-top: 0.5px solid #666;
    width: 250px;
    margin-right: 0;
  }
  
  .footer-section {
    margin-top: 40px;
    text-align: center;
    font-size: 12px;
  }
</style>

<!-- Document Fields -->
<table class="header-table">
  <tr>
    <td><strong>العميل:</strong> {{ doc.party_name or "" }}</td>
    <td><strong>التاريخ:</strong> {{ frappe.utils.formatdate(doc.transaction_date) if doc.transaction_date else "" }}</td>
  </tr>
  <tr>
    <td><strong>رقم العرض:</strong> {{ doc.name or "" }}</td>
    <td><strong>العملة:</strong> {{ doc.currency or "SAR" }}</td>
  </tr>
</table>

<!-- Items Table with Grouping -->
<div class="boq-container">
  <table class="boq-table">
    <thead>
      <tr>
        <th>Sr</th>
        <th>البند</th>
        <th>الوصف</th>
        <th>الوحدة</th>
        <th>الكمية</th>
        <th>السعر</th>
        <th>المبلغ ({{ doc.currency or "SAR" }})</th>
      </tr>
    </thead>
    <tbody>
      {% set grouped_items = {} %}
      {% for row in doc.items %}
        {% if row.item_group %}
          {% if not grouped_items[row.item_group] %}
            {% set _ = grouped_items.update({row.item_group: []}) %}
          {% endif %}
          {% set _ = grouped_items[row.item_group].append(row) %}
        {% endif %}
      {% endfor %}

      {% for group, items in grouped_items.items() %}
        <!-- Group Row -->
        <tr class="group-row">
          <td colspan="7" style="text-align:center">{{ group }}</td>
        </tr>
        {% for row in items %}
        <!-- Normal Item Row -->
        <tr>
          <td class="num-col">{{ loop.index }}</td>
          <td class="item-no">{{ row.item_code or "" }}</td>
          <td>{{ row.description or "" }}</td>
          <td class="num-col">{{ row.uom or "" }}</td>
          <td class="num-col">{{ row.qty or "" }}</td>
          <td class="num-col">{{ row.rate or "" }}</td>
          <td class="num-col">{{ row.amount or "" }}</td>
        </tr>
        {% endfor %}
      {% endfor %}
    </tbody>
  </table>
</div>

<!-- Totals Section -->
<div class="total-container">
  <div class="section-title">الإجماليات</div>
  <table class="total_table">
    <tr>
      <td>الاجمالي بدون ضريبه ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("total") }}</td>
    </tr>
    <tr>
      <td>اجمالي الضريبة  ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("total_taxes_and_charges") }}</td>
    </tr>
    <tr>
      <td>الاجمالي مع الضريبة  ({{ doc.currency or "SAR" }})</td>
      <td>{{ doc.get_formatted("grand_total") }}</td>
    </tr>
  </table>
</div>

<!-- Payment Terms Table -->
{% if doc.payment_schedule %}
<div class="total-container">
  <div class="section-title">شروط الدفع / Payment Terms</div>
  <table class="total_table">
    <thead>
      <tr>
         <td><strong>البند / Payment Term</strong></td>
        <td><strong>نسبة الدفع / Invoice Portion%</strong></td>
        <td><strong>التاريخ / Date</strong></td>
        <td><strong>المبلغ / Amount</strong></td>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.payment_schedule %}
      <tr>
         <td>{{ row.payment_term or "" }}</td>
        <td>{{ row.invoice_portion or "" }}</td>
        <td>{{ frappe.utils.formatdate(row.due_date) if row.due_date else "" }}</td>
        <td>{{ row.payment_amount or "" }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>
{% endif %}

