{# ===== Separate normal items and other charges ===== #}
{% set normal_items = doc.items | selectattr("item_code", "ne", "تكاليف اضافيه") | list %}
{% set other_item = doc.items | selectattr("item_code", "equalto", "تكاليف اضافيه") | list | first %}
{% set other_charges_amount = other_item.amount if other_item else 0 %}

<table class="items-table">
    <thead>
        <tr style="background:#e0e0e0;">
            <th>مسلسل<br><span style="font-size:9px;">No.</span></th>
            <th>كود الصنف<br><span style="font-size:9px;">Item Code</span></th>
            <th>الوصف <br><span style="font-size:9px;">Description </span></th>
            <th>سعر الوحده<br><span style="font-size:9px;">Price Per Unit</span></th>
            <th>الكمية<br><span style="font-size:9px;">Qty</span></th>
            <th>من<br><span style="font-size:8px;">From</span></th>
            <th>الى<br><span style="font-size:8px;">To</span></th>
            <th>تكاليف النقل<br><span style="font-size:8px;">Trans Charge</span></th>
            <th>تكاليف اضافيه<br><span style="font-size:8px;">Other Trans</span></th>
            <th>الاجمالي <br><span style="font-size:9px;">Total</span></th>
            <th>الضريبة<br><span style="font-size:9px;">Tax</span></th>
        </tr>
    </thead>
    <tbody>
    {% set total_amount = 0 %}
    {% set total_net = 0 %}

    {% for item in normal_items %}
        {% set amount = item.rate * item.qty %}
        {% set discount_amount = item.discount_amount or 0 %}
        {% set net_before_tax = amount - discount_amount %}
        {% set vat = (doc.total_taxes_and_charges or 0) %}
        {% set net = net_before_tax + vat %}

        {% set total_amount = total_amount + net_before_tax %}
        {% set total_net = total_net + net %}

        <tr>
            <td>{{ loop.index }}</td>
            <td>{{ item.item_code }}</td>
            <td>{{ item.description or "-" }}</td>
            <td>{{ "%.2f"|format(item.rate) }}</td>
            <td>{{ "%.2f"|format(item.qty) }}</td>
            <td>{{ item.custom_origin_city or "-" }}</td>
            <td>{{ item.custom_destination_city or "-" }}</td>
            <td>{{ item.custom_trans_charge or "-" }}</td>
            <td>{{ item.custom_other_charge or "-" }}</td>
            <td>{{ "%.2f"|format(amount) }}</td>
            <td>{{ "%.2f"|format(vat) }}</td>
        </tr>
    {% endfor %}

    <tr style="background:#f0f0f0;">
        <td colspan="4">الإجمالي الكلي</td>
        <td>{{ "%.2f"|format(doc.total_qty) }}</td>
        <td>-</td>
        <td>-</td>
        <td>-</td>
        <td>-</td>
        <td>-</td>
        <td>{{ "%.2f"|format(doc.grand_total or total_net) }}</td>
    </tr>
    </tbody>
</table>

<div style="display: flex; justify-content: space-between; align-items: flex-start;">

    <div style="width: 25%; text-align: center; padding-top: 20px;">
        {% if not is_draft %}
        <img src="data:image/png;base64, {{ get_zatca_phase_1_qr_for_invoice(doc.name) }}"
