{# ========================================================= #}
{# SEPARATE NORMAL ITEMS                                     #}
{# ========================================================= #}

{% set normal_items =
    doc.items
    | selectattr(
        "item_code",
        "ne",
        "تكاليف اضافيه"
    )
    | list
%}


{% set other_item =
    doc.items
    | selectattr(
        "item_code",
        "equalto",
        "تكاليف اضافيه"
    )
    | list
    | first
%}


{% set other_charges_amount =
    other_item.net_amount
    if other_item else 0
%}



{# ========================================================= #}
{# TABLE TOTALS                                              #}
{# ========================================================= #}

{% set totals = namespace(
    qty=0,
    net=0,
    vat=0,
    gross=0
) %}



{# ========================================================= #}
{# ITEMS TABLE                                               #}
{# ========================================================= #}

<table class="items-table">


<thead>


<tr style="background:#e0e0e0;">


<th>

    مسلسل

    <br>

    <span style="font-size:9px;">
        No.
    </span>

</th>



<th>

    كود الصنف

    <br>

    <span style="font-size:9px;">
        Item Code
    </span>

</th>



<th>

    الوصف

    <br>

    <span style="font-size:9px;">
        Description
    </span>

</th>



<th>

    سعر الوحده

    <br>

    <span style="font-size:9px;">
        Price Per Unit
    </span>

</th>



<th>

    الكمية

    <br>

    <span style="font-size:9px;">
        Qty
    </span>

</th>



<th>

    الاجمالي

    <br>

    <span style="font-size:9px;">
        Total
    </span>

</th>



<th>

    الضريبة

    <br>

    <span style="font-size:9px;">
        VAT
    </span>

</th>



<th>

    الاجمالي بعد الضريبة

    <br>

    <span style="font-size:9px;">
        Total After Tax
    </span>

</th>


</tr>


</thead>



<tbody>



{% for item in normal_items %}



{# ========================================================= #}
{# NET AMOUNT                                                #}
{# ========================================================= #}

{% set net_before_tax =
    item.net_amount or 0
%}



{# ========================================================= #}
{# NET RATE                                                  #}
{# ========================================================= #}

{% if item.qty %}

    {% set net_rate =
        net_before_tax / item.qty
    %}

{% else %}

    {% set net_rate =
        item.net_rate
        or item.rate
        or 0
    %}

{% endif %}



{# ========================================================= #}
{# ITEM VAT                                                  #}
{# ========================================================= #}

{% set item_tax = namespace(
    amount=0,
    found=false
) %}



{# ========================================================= #}
{# ERPNext VERSION 16                                        #}
{# ========================================================= #}

{% if doc.get("item_wise_tax_details") %}


    {% for tax_detail in doc.get("item_wise_tax_details") %}


        {% if tax_detail.item_row == item.name %}


            {% set item_tax.amount =
                item_tax.amount
                +
                (
                    (tax_detail.amount or 0)
                    /
                    (doc.conversion_rate or 1)
                )
            %}


            {% set item_tax.found = true %}


        {% endif %}


    {% endfor %}


{% endif %}



{# ========================================================= #}
{# ERPNext VERSION 15 AND OLDER                              #}
{# ========================================================= #}

{% if not item_tax.found %}


    {% for tax in doc.taxes %}


        {% if tax.item_wise_tax_detail %}


            {% set tax_details =
                json.loads(
                    tax.item_wise_tax_detail or "{}"
                )
            %}



            {% if item.item_code in tax_details %}


                {% set tax_data =
                    tax_details[item.item_code]
                %}



                {# ========================================= #}
                {# DICTIONARY FORMAT                         #}
                {# ========================================= #}

                {% if tax_data is mapping %}


                    {% set current_tax_amount =
                        tax_data.get("tax_amount")
                        or tax_data.get("amount")
                        or 0
                    %}


                    {% set item_tax.amount =
                        item_tax.amount
                        +
                        current_tax_amount
                    %}


                    {% set item_tax.found = true %}



                {# ========================================= #}
                {# LIST FORMAT [RATE, TAX AMOUNT]            #}
                {# ========================================= #}

                {% else %}


                    {% if tax_data|length > 1 %}


                        {% set item_tax.amount =
                            item_tax.amount
                            +
                            (tax_data[1] or 0)
                        %}


                    {% endif %}


                    {% set item_tax.found = true %}


                {% endif %}


            {% endif %}


        {% endif %}


    {% endfor %}


{% endif %}



{# ========================================================= #}
{# FALLBACK TAX CALCULATION                                  #}
{# ========================================================= #}

{% if not item_tax.found %}


    {% set fallback_tax = namespace(
        amount=0
    ) %}


    {% set item_tax_map = {} %}


    {% if item.item_tax_rate %}


        {% set item_tax_map =
            json.loads(
                item.item_tax_rate or "{}"
            )
        %}


    {% endif %}



    {% for tax in doc.taxes %}


        {% if
            tax.charge_type == "On Net Total"
            and (tax.rate or 0) != 0
        %}


            {% set tax_rate =
                tax.rate or 0
            %}



            {# ============================================= #}
            {# ITEM TAX TEMPLATE RATE                        #}
            {# ============================================= #}

            {% if
                tax.account_head
                and tax.account_head in item_tax_map
            %}


                {% set tax_rate =
                    item_tax_map[tax.account_head]
                %}


            {% endif %}



            {# ============================================= #}
            {# -1 MEANS TAX NOT APPLICABLE                   #}
            {# ============================================= #}

            {% if tax_rate != -1 %}


                {% set calculated_tax =
                    (
                        net_before_tax
                        *
                        tax_rate
                        /
                        100
                    )
                %}



                {% if tax.add_deduct_tax == "Deduct" %}


                    {% set calculated_tax =
                        calculated_tax * -1
                    %}


                {% endif %}



                {% set fallback_tax.amount =
                    fallback_tax.amount
                    +
                    calculated_tax
                %}


            {% endif %}


        {% endif %}


    {% endfor %}



    {% set item_tax.amount =
        fallback_tax.amount
    %}


{% endif %}



{# ========================================================= #}
{# TOTAL AFTER VAT                                           #}
{# ========================================================= #}

{% set total_after_tax =
    net_before_tax
    +
    item_tax.amount
%}



{# ========================================================= #}
{# ACCUMULATE TABLE TOTALS                                   #}
{# ========================================================= #}

{% set totals.qty =
    totals.qty
    +
    (item.qty or 0)
%}


{% set totals.net =
    totals.net
    +
    net_before_tax
%}


{% set totals.vat =
    totals.vat
    +
    item_tax.amount
%}


{% set totals.gross =
    totals.gross
    +
    total_after_tax
%}



{# ========================================================= #}
{# PRINT ITEM ROW                                            #}
{# ========================================================= #}

<tr>


<td>

    {{ loop.index }}

</td>



<td>

    {{ item.item_code }}

</td>



<td>

    {{ item.description or "-" }}

</td>



<td>

    {{ "%.2f"|format(net_rate or 0) }}

</td>



<td>

    {{ "%.2f"|format(item.qty or 0) }}

</td>



<td>

    {{ "%.2f"|format(net_before_tax or 0) }}

</td>



<td>

    {{ "%.2f"|format(item_tax.amount or 0) }}

</td>



<td class="bold">

    {{ "%.2f"|format(total_after_tax or 0) }}

</td>


</tr>



{% endfor %}



{# ========================================================= #}
{# ITEMS TOTAL ROW                                           #}
{# ========================================================= #}

<tr style="background:#f0f0f0;">


<td colspan="4">

    الإجمالي الكلي

    <br>

    <span style="font-size:9px;">
        Total
    </span>

</td>



<td>

    {{ "%.2f"|format(totals.qty) }}

</td>



<td>

    {{ "%.2f"|format(totals.net) }}

</td>



<td>

    {{ "%.2f"|format(totals.vat) }}

</td>



<td>

    {{ "%.2f"|format(totals.gross) }}

</td>


</tr>


</tbody>

</table>



