    - غير شامل ضريبة القيمة المضافة

</td>



<td style="text-align:left;">

    {{ doc.get_formatted("net_total") }}

</td>


</tr>



{# ========================================================= #}
{# TOTAL VAT                                                 #}
{# ========================================================= #}

<tr>


<td
    style="
        text-align:right;
        direction:ltr;
    "
>

    Total VAT

</td>



<td style="text-align:right;">

    مجموع ضريبة القيمة المضافة

</td>



<td style="text-align:left;">


{% if doc.get("custom_total_taxes") is not none %}


    {{
        frappe.utils.fmt_money(
            doc.custom_total_taxes or 0,
            currency=doc.currency
        )
    }}


{% else %}


    {{ doc.get_formatted("total_taxes_and_charges") }}


{% endif %}


</td>


</tr>



{# ========================================================= #}
{# RETENTION                                                 #}
{# ========================================================= #}

{% set total_retention_amount =
    doc.retention
    | sum(attribute="retention_amount")
    if doc.get("retention")
    else 0
%}


<tr>


<td
    style="
        text-align:right;
        direction:ltr;
    "
>

    Retention Discount

</td>



