</td>



<td style="text-align:left;">

    {{
        frappe.utils.fmt_money(
            total_retention_amount,
            currency=doc.currency
        )
    }}

</td>


</tr>




<tr>


<td
    style="
        text-align:right;
        width:35%;
        direction:ltr;
    "
>

Discount
</td>



<td
    style="
        text-align:right;
        width:45%;
    "
>

    الخصم
</td>



<td
    style="
        text-align:left;
        width:20%;
    "
>

    {{ doc.get_formatted("discount_amount") }}

</td>


</tr>







{# ========================================================= #}
{# GRAND TOTAL                                               #}
{# ========================================================= #}

<tr
    style="
        border-bottom:2px solid #000;
    "
>


<td
    style="
        text-align:right;
        direction:ltr;
    "
>

    Total Amount Due

</td>



<td style="text-align:right;">

    إجمالي المبلغ المستحق

</td>



